;/* app.js */
'use strict';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='farnoor.workspace.v1';
const statuses=['Pending','In progress','Completed','Cancelled'];
function normalizeDate(value){
 const raw=String(value).trim().replace(/[০-৯]/g,c=>'০১২৩৪৫৬৭৮৯'.indexOf(c));
 const match=raw.match(/^(\d{1,2})[/.\-](\d{1,2})[/.\-](\d{2}|\d{4})$/);
 if(!match)throw Error('Use a date like 1/1/26 or 01/01/2026.');
 const day=Number(match[1]),month=Number(match[2]),year=match[3].length===2?2000+Number(match[3]):Number(match[3]);
 const test=new Date(year,month-1,day);
 if(year<1900||year>2199||test.getFullYear()!==year||test.getMonth()!==month-1||test.getDate()!==day)throw Error('Please enter a valid date.');
 return `${String(day).padStart(2,'0')}/${String(month).padStart(2,'0')}/${year}`;
}
function initialState(){return {profile:{username:'Farnoor Admin',email:'admin@farnoor.example',photo:''},records:{}};}
function validateState(data){
 if(!data||!data.profile||typeof data.profile.username!=='string'||!data.profile.username.trim()||data.profile.username.length>60||typeof data.profile.email!=='string'||!/^\S+@\S+\.\S+$/.test(data.profile.email)||data.profile.email.length>120||typeof data.profile.photo!=='string'||(data.profile.photo&&!/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(data.profile.photo))||data.profile.photo.length>2800000||!data.records||typeof data.records!=='object'||Array.isArray(data.records))throw Error('Invalid backup file.');
 for(const department of DEPARTMENTS)for(const page of department.pages){const rows=data.records[page.id]||[];if(!Array.isArray(rows)||rows.length>10000)throw Error('Invalid records.');const ids=new Set();for(const row of rows){if(typeof row.id!=='string'||ids.has(row.id)||typeof row.reference!=='string'||typeof row.name!=='string'||row.reference.length>120||row.name.length>200||!Number.isFinite(Number(row.quantity))||Number(row.quantity)<0||!statuses.includes(row.status))throw Error('Invalid record in backup.');normalizeDate(row.date);ids.add(row.id);}}
 if(data.ledger){for(const kind of ['credit','debit']){if(!Array.isArray(data.ledger[kind])||data.ledger[kind].length>10000)throw Error('Invalid account files.');for(const file of data.ledger[kind]){if(typeof file.id!=='string'||file.id.length>120||typeof file.createdAt!=='string'||!Number.isFinite(Date.parse(file.createdAt))||!Array.isArray(file.rows)||file.rows.length>10000)throw Error('Invalid account file.');for(const row of file.rows){normalizeDate(row.date);if(!Number.isSafeInteger(row.cents)||row.cents<0||typeof row.remarks!=='string'||row.remarks.length>500)throw Error('Invalid account row.');}}}}
 if(data.orderFiles){if(!Array.isArray(data.orderFiles)||data.orderFiles.length>10000)throw Error('Invalid order files.');const ids=new Set();for(const file of data.orderFiles){if(typeof file.id!=='string'||file.id.length>120||ids.has(file.id)||!Number.isFinite(Date.parse(file.createdAt))||!Array.isArray(file.rows)||file.rows.length>10000)throw Error('Invalid order file.');ids.add(file.id);for(const row of file.rows){for(const key of ['buyer','style','item','remarks'])if(typeof row[key]!=='string'||row[key].length>500)throw Error('Invalid order details.');if(!Number.isSafeInteger(row.qty)||row.qty<1)throw Error('Invalid order quantity.');normalizeDate(row.orderDate);normalizeDate(row.shipmentDate);}}}
 if(data.productionSchedules){if(!Array.isArray(data.productionSchedules)||data.productionSchedules.length>10000)throw Error('Invalid production schedules.');const ids=new Set();for(const file of data.productionSchedules){if(typeof file.id!=='string'||ids.has(file.id)||file.id.length>120||!DEPARTMENTS.flatMap(d=>d.pages).some(p=>p.section===file.section)||!Number.isFinite(Date.parse(file.createdAt))||typeof file.month!=='string'||!/^\d{1,2}\/\d{4}$/.test(file.month)||!['None','Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].includes(file.weekly)||!Array.isArray(file.extra)||file.extra.some(day=>!Number.isInteger(day)||day<1||day>31)||!Array.isArray(file.rows)||file.rows.length>10000||!file.journal||typeof file.journal!=='object'||Array.isArray(file.journal))throw Error('Invalid saved production plan.');const [month,year]=file.month.split('/').map(Number);if(month<1||month>12||year<1900||year>2199||file.extra.some(day=>day>new Date(year,month,0).getDate()))throw Error('Invalid production month.');ids.add(file.id);for(const row of file.rows){for(const key of ['buyer','item','style','remarks'])if(typeof row[key]!=='string'||row[key].length>500)throw Error('Invalid production details.');for(const key of ['orderQty','totalQty','firstTarget','dailyTarget'])if(!Number.isSafeInteger(row[key])||row[key]<0||row[key]>1000000000)throw Error('Invalid production quantity.');normalizeDate(row.startDate);}for(const [date,actual]of Object.entries(file.journal)){normalizeDate(date);if(!actual||typeof actual!=='object'||String(actual.remarks||'').length>500||!Number.isFinite(Number(actual.hours??10))||Number(actual.hours??10)<=0||Number(actual.hours??10)>24||!/^[০-৯0-9,]*$/.test(String(actual.output||'')))throw Error('Invalid daily output.');}}}
 StoreCore.validateFiles(data.records,normalizeDate);
 window.FarnoorPayrollCore?.validateRows(data.records.payroll,normalizeDate);
 return data;
}
let state=initialState();let storageWarning='';
let activePage=null,opened=new Set(),query='',filter='All statuses',editingId=null,pendingPhoto='',sessionActive=false;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function avatar(photo,name){return photo?`<img class="avatar-image" src="${esc(photo)}" alt="User photo">`:`<span class="avatar-initial">${esc(name.slice(0,1).toUpperCase())}</span>`;}
function renderProfile(){$('#username').textContent=state.profile.username;$('#avatar').innerHTML=avatar(state.profile.photo,state.profile.username);}
function pageInfo(id){for(const department of DEPARTMENTS){const page=department.pages.find(p=>p.id===id);if(page)return {department,page};}return null;}
const submenuLooks=new Map();
const departmentHues={admin:195,packing:95,sewing:330,hr:333,accounts:150,commercial:215,merch:265,knitting:185,inventory:38,production:200,cutting:18,finishing:300,quality:80,sample:348,maintenance:215,electrical:48};
for(const department of DEPARTMENTS){
 const keys=new Set();
 for(const page of department.pages.filter(p=>!p.hidden)){
  if(!page.groupEntry)keys.add('page:'+page.id);
  if(page.parent)keys.add('group:'+department.id+':'+page.parent);
  page.navPath?.forEach((part,index)=>keys.add('group:'+department.id+':'+page.navPath.slice(0,index+1).join('/')));
 }
 for(const key of keys){
  const index=submenuLooks.size;let hue=Math.round(index*137.508)%360;
  const distance=Math.abs(hue-departmentHues[department.id]);
  if(Math.min(distance,360-distance)<65)hue=(hue+150)%360;
  const saturation=58+index%17,lightness=91+(index%5)*.7;
  submenuLooks.set(key,{hue,saturation,lightness,shape:['rounded','ticket','rail','pill','underline'][index%5]});
 }
}
function submenuAttributes(key,depth=0){
 const look=submenuLooks.get(key),{hue:h,saturation:s,lightness:l,shape}=look;
 return `data-sub-style="${shape}" data-sub-depth="${depth}" style="--sub-bg:hsl(${h} ${s}% ${l}%);--sub-edge:hsl(${h} ${s-15}% 75%);--sub-ink:hsl(${h} 42% 25%);--sub-accent:hsl(${h} 45% 48%)"`;
}
function renderNavigation(){
 const pageButton=(p,depth=0)=>`<button class="page-button ${activePage===p.id?'active':''}" data-page="${p.id}" ${submenuAttributes('page:'+p.id,depth)} aria-expanded="${activePage===p.id}"><span class="submenu-icon" aria-hidden="true">${p.icon}</span><span class="submenu-label">${esc(p.name)}</span></button>`;
 const tree=(department,pages,depth=0,path=[])=>{const seen=new Set();return pages.map(page=>{if(!page.navPath||page.navPath.length<=depth)return page.groupEntry?'':pageButton(page,depth);const label=page.navPath[depth];if(seen.has(label))return '';seen.add(label);const children=pages.filter(p=>p.navPath?.[depth]===label),nextPath=[...path,label],key=department.id+':'+nextPath.join('/'),entry=children.find(p=>p.groupEntry&&p.navPath.length===depth+1);return `<button class="page-button schedule-group" data-group="${esc(key)}" ${entry?`data-group-page="${entry.id}"`:''} ${submenuAttributes('group:'+key,depth)} aria-expanded="${opened.has(key)}"><span class="submenu-icon" aria-hidden="true">${({'ORDER':'▣','Admin':'♛','Utilities':'⚒','Management':'▦','HR Info':'♙','Attendance':'◷','Schedule':'▦','Schedule Report':'▤','Sewing':'⚙','Quality':'◎','Sample':'✂'})[label]||'▥'}</span><span class="submenu-label">${esc(label)}</span><span class="submenu-toggle">${opened.has(key)?'−':'+'}</span></button>${opened.has(key)?`<div class="nested-pages">${tree(department,children,depth+1,nextPath)}</div>`:''}`;}).join('');};
 $('#navigation').innerHTML=DEPARTMENTS.filter(d=>d.placeholder?true:d.navigationOnly?(window.FarnoorAccess?.canPage('sewing-plan')||DEPARTMENTS.find(item=>item.id==='production')?.pages.some(p=>window.FarnoorAccess?.canPage(p.permissionPage||p.id))):d.pages.some(p=>!p.hidden&&(window.FarnoorAccess?.canPage(p.permissionPage||p.id)??false))).map(d=>{const seen=new Set();const pages=d.pages.filter(p=>!p.hidden&&(window.FarnoorAccess?.canPage(p.permissionPage||p.id)??false));return `<div class="department"><button class="department-button" data-department="${d.id}" style="--color:${d.color}" aria-expanded="${opened.has(d.id)}"><span class="icon" aria-hidden="true">${d.icon}</span><span>${esc(d.name)}</span><span class="chevron">${opened.has(d.id)?'−':'+'}</span></button>${opened.has(d.id)?`<div class="pages">${pages.some(p=>p.navPath)?tree(d,pages):pages.map(p=>{if(!p.parent)return pageButton(p);if(seen.has(p.parent))return '';seen.add(p.parent);const key=d.id+':'+p.parent;return `<button class="page-button account-group" data-group="${key}" ${submenuAttributes('group:'+key)} aria-expanded="${opened.has(key)}"><span class="submenu-icon" aria-hidden="true">${p.parent==='CREDIT'?'⊕':p.parent==='DEBIT'?'⊖':'▤'}</span><span class="submenu-label">${esc(p.parent)}</span><span class="submenu-toggle">${opened.has(key)?'−':'+'}</span></button>${opened.has(key)?`<div class="nested-pages">${pages.filter(child=>child.parent===p.parent).map(child=>pageButton(child,1)).join('')}</div>`:''}`;}).join('')}</div>`:''}</div>`;}).join('');
}
function openNavigationBranch(departmentId,path=[]){opened.clear();opened.add(departmentId);path.forEach((part,index)=>opened.add(departmentId+':'+path.slice(0,index+1).join('/')));}
function closeNavigationBranch(key){for(const item of [...opened])if(item===key||item.startsWith(key+':')||item.startsWith(key+'/'))opened.delete(item);}
$('#navigation').addEventListener('click',e=>{const group=e.target.closest('[data-group]');if(!group)return;const key=group.dataset.group;if(opened.has(key)){closeNavigationBranch(key);activePage=null;renderClosed();}else{const separator=key.indexOf(':');openNavigationBranch(key.slice(0,separator),key.slice(separator+1).split('/'));activePage=null;renderClosed();if(group.dataset.groupPage)goPage(group.dataset.groupPage);}renderNavigation();});
function goPage(id){const info=pageInfo(id);if(!info)return;document.body.dataset.activeDepartment=info.department.id;openNavigationBranch(info.department.id,info.page.navPath||(info.page.parent?[info.page.parent]:[]));activePage=id;query='';filter='All statuses';renderNavigation();renderPage();}
const requistionListColumns=[['description','DESCRIPTION'],['location','LOCATION'],['size','SIZE'],['qty','QTY'],['unitPrice','UNIT PRICE'],['totalPrice','TOTAL PRICE']];
let requistionListRows=[{}];
function requistionListRow(row,index){const editable=window.FarnoorAccess?.canAction('requistion-input-report','edit')===true;return '<tr><td class="requistion-sl">'+(index+1)+'</td>'+requistionListColumns.map(([key,label])=>'<td><input type="text" data-requistion-row="'+index+'" data-requistion-field="'+key+'" aria-label="'+label+' row '+(index+1)+'" '+(['qty','unitPrice','totalPrice'].includes(key)||requistionIsStore()&&key==='location'?'inputmode="decimal" ':'')+'value="'+esc(row[key]||'')+'" '+(editable?'':'readonly')+'></td>').join('')+'</tr>';}
function requistionListPaper(){return '<section class="requistion-list-paper"><header class="requistion-company"><h1>FARNOOR GARMENTS LTD.</h1><p>1028/1/2 Malibagh Bazar Road, Dhaka-1217</p><h2>REQUISTION</h2></header><div class="requistion-list-scroll"><table class="requistion-list-table"><colgroup><col style="width:5%"><col style="width:30%"><col style="width:16%"><col style="width:11%"><col style="width:10%"><col style="width:14%"><col style="width:14%"></colgroup><thead><tr><th rowspan="2" scope="col">SL</th><th rowspan="2" scope="col">DESCRIPTION</th><th rowspan="2" scope="col">LOCATION</th><th rowspan="2" scope="col">SIZE</th><th rowspan="2" scope="col">QTY</th><th colspan="2" scope="colgroup">APPRIX RATE</th></tr><tr><th scope="col">UNIT PRICE</th><th scope="col">TOTAL PRICE</th></tr></thead><tbody id="requistionListBody">'+requistionListRows.map(requistionListRow).join('')+'</tbody></table></div></section>';}
function requistionListEnter(event){const input=event.target;if(event.key!=='Enter'||event.isComposing||!input.matches?.('[data-requistion-field]')||!window.FarnoorAccess?.canAction('requistion-input-report','edit'))return;event.preventDefault();const index=Number(input.dataset.requistionRow);if(!requistionListRows[index])return;requistionListRows[index][input.dataset.requistionField]=input.value;const next=index+1;if(!requistionListRows[next]){requistionListRows.push({});$('#requistionListBody').insertAdjacentHTML('beforeend',requistionListRow(requistionListRows[next],next));}document.querySelector('[data-requistion-row="'+next+'"][data-requistion-field="description"]')?.focus();}
$('#main').addEventListener('input',event=>{const input=event.target;if(!input.matches?.('[data-requistion-field]')||!window.FarnoorAccess?.canAction('requistion-input-report','edit'))return;const row=requistionListRows[Number(input.dataset.requistionRow)];if(row)row[input.dataset.requistionField]=input.value;});
$('#main').addEventListener('keydown',requistionListEnter);
const requistionDepartments=["Administration","Commercial","Merchandising","Knitting and Dyeing","Store","Driver","Production","Quality","Cutting","Finishing","Maintenance","Electrical","Sample"];
const requistionRequesterNames=["Majed Jahangir","Syed Ashraful Haque","Rafe-Uz-Zaman","Masud Rana","Gupal chandra Das","Ferdous","Tawhidul islam Shagor","S.M. Abdus Salam","Md. Liton Akhter","Safiqul Alam","Ashrafuzzaman","Abdus Sattar","Monir Hossain","Sohag Mia","Abul Hasan","Awrangajeb Mozumder","Zakir Hossain","Shahin Fokir","Sujon Mia","Younus ali","Feruj Shikder","Karun Kumar Barman","Mohammad Arif Billah","Mehedi Hasan","Md. Mahamudul Hasan","Mahim Howlader","Kabir Hossain","Fazlur Rahman","Md. Abdul Latif","Dalu Mia","Dipak","Asaduzzaman","Pinku Baral","Md. Anamul Haque","Mahbubur Rahman","Humayun","Bourhan Uddin","Masum","Nasir Uddin","Sree Bipul Kumar Ray","Mohammad Ali","Forkan","Shohidul Islam","Ibrahim Mia","Rakib Hossain Meem","Shahadat","Shamsuzzaman","Akhter","Jalal Sharif","Munna","Lutfor Rahman Babu","Md. Sohel Rana","Jihad Hossain","Anwar Hossain","Nazia Nahar Suchona","Rimon Biswas","Abdur Rashid","Saiful Islam","Rubel Bhuiyan","RIPON KUMAR DAS","LAMUSHA ALI","Jannatul Mahbuba","Majharul Islam","Jasim Talukdar"];
const requistionCompanies=[{name:'FARNOOR GARMENTS LTD.',address:'1028/1/2 Malibagh Bazar Road, Dhaka-1217'},{name:'FARNOOR GARMENTS LTD.-UNIT-2',address:'454, BaburChala, Alimpara, Pirujali, Gazipur'}];
const requistionRequester={company:requistionCompanies[0].name,department:'',requistion:'',name:''};
function requistionCurrentCompany(){return requistionCompanies.find(company=>company.name===requistionRequester.company)||requistionCompanies[0];}
function requistionRequesterValues(key){return key==='company'?requistionCompanies.map(company=>company.name):key==='department'?requistionDepartments:key==='requistion'?['Requistion','Monthly Requistion']:requistionRequesterNames;}
function requistionRequesterReady(){return Boolean(requistionRequester.department.trim()&&requistionRequester.name.trim());}
function requistionSuggestionKey(value){return String(value||'').normalize('NFKC').replace(/[০-৯]/g,d=>'০১২৩৪৫৬৭৮৯'.indexOf(d)).trim().replace(/\s+/g,' ').toLocaleLowerCase();}
function requistionRequesterSuggestions(key,query){const match=requistionSuggestionKey(query);if(Array.from(match).length<2)return [];return requistionRequesterValues(key).filter(value=>requistionSuggestionKey(value).includes(match));}
function requistionRequesterOptions(key){return requistionRequesterSuggestions(key,requistionRequester[key]).map(value=>'<option value="'+esc(value)+'"></option>').join('');}
function requistionRequesterPicker(){return '<section class="requistion-requester-picker">'+[['company','Company'],['department','Department'],['requistion','Requistion'],['name','Prepared by']].map(([key,label])=>'<label for="requistion-request-'+key+'">'+label+'</label><div class="requistion-combobox"><input id="requistion-request-'+key+'" type="text" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="requistion-'+key+'-choices" maxlength="120" '+(key==='company'?'readonly ':'')+'placeholder="'+(key==='company'?'Select Company':'Type 2 characters or enter a new '+label)+'" autocomplete="off" value="'+esc(requistionRequester[key])+'"><button type="button" class="requistion-dropdown-toggle" data-requistion-dropdown="'+key+'" aria-label="Show '+label+' list" aria-controls="requistion-'+key+'-choices"><span aria-hidden="true">▾</span></button><div class="requistion-choice-list" id="requistion-'+key+'-choices" role="listbox" aria-label="'+label+' options" hidden></div></div>').join('')+'</section>';}
function requistionRequesterCloseChoices(){for(const key of ['company','department','requistion','name']){const menu=document.getElementById('requistion-'+key+'-choices'),input=document.getElementById('requistion-request-'+key);if(menu)menu.hidden=true;if(input){input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');}}}
function requistionRequesterShowChoices(key,all=false){if(!['company','department','requistion','name'].includes(key))return;requistionRequesterCloseChoices();const input=document.getElementById('requistion-request-'+key),menu=document.getElementById('requistion-'+key+'-choices');if(!input||!menu)return;const values=all||key==='company'?requistionRequesterValues(key):requistionRequesterSuggestions(key,requistionRequester[key]);menu.innerHTML=values.map((value,index)=>'<button type="button" role="option" tabindex="-1" aria-selected="false" id="requistion-'+key+'-choice-'+index+'" data-requistion-choice="'+key+'" data-requistion-value="'+esc(value)+'">'+esc(value)+'</button>').join('');menu.hidden=!values.length;menu.dataset.activeIndex='-1';input.setAttribute('aria-expanded',String(!menu.hidden));}
function requistionRequesterChoose(key,value){if(!window.FarnoorAccess?.canPage('requistion-new-input')||!['company','department','requistion','name'].includes(key))return;const values=requistionRequesterValues(key);if(!values.includes(value))return;requistionRequester[key]=value;renderRequistion('new-input');if(!requistionRequesterReady())document.getElementById('requistion-request-'+(key==='department'?'name':'department'))?.focus();}
$('#main').addEventListener('mousedown',event=>{if(event.target.closest?.('[data-requistion-choice],[data-requistion-dropdown]'))event.preventDefault();});
$('#main').addEventListener('click',event=>{if(document.body.dataset.activeDepartment!=='requistion'||!window.FarnoorAccess?.canPage('requistion-new-input'))return;const choice=event.target.closest?.('[data-requistion-choice]');if(choice){requistionRequesterChoose(choice.dataset.requistionChoice,choice.dataset.requistionValue);return;}const toggle=event.target.closest?.('[data-requistion-dropdown]');if(toggle){const key=toggle.dataset.requistionDropdown,menu=document.getElementById('requistion-'+key+'-choices');if(menu&&!menu.hidden)requistionRequesterCloseChoices();else{requistionRequesterShowChoices(key,true);document.getElementById('requistion-request-'+key)?.focus();}return;}if(!event.target.closest?.('.requistion-combobox'))requistionRequesterCloseChoices();});
$('#main').addEventListener('keydown',event=>{const input=event.target;if(!['requistion-request-company','requistion-request-department','requistion-request-requistion','requistion-request-name'].includes(input.id)||event.isComposing)return;const key=input.id.replace('requistion-request-',''),menu=document.getElementById('requistion-'+key+'-choices');if(!menu)return;if(event.key==='Escape'){requistionRequesterCloseChoices();return;}if(['ArrowDown','ArrowUp'].includes(event.key)){event.preventDefault();if(menu.hidden)requistionRequesterShowChoices(key,true);const options=[...menu.querySelectorAll('[data-requistion-choice]')];if(!options.length)return;let index=Number(menu.dataset.activeIndex??-1);index=event.key==='ArrowDown'?Math.min(index+1,options.length-1):Math.max(index-1,0);menu.dataset.activeIndex=String(index);options.forEach((option,i)=>{option.setAttribute('aria-selected',String(i===index));option.classList.toggle('active',i===index);});input.setAttribute('aria-activedescendant',options[index].id);options[index].scrollIntoView({block:'nearest'});return;}if(event.key==='Enter'){event.preventDefault();const options=[...menu.querySelectorAll('[data-requistion-choice]')],selected=!menu.hidden?options[Number(menu.dataset.activeIndex)]:null;if(selected)requistionRequesterChoose(key,selected.dataset.requistionValue);else requistionRequesterChange(event,true);}});
let requistionEntryWide=false;
function requistionNewView(){const ready=requistionRequesterReady();return '<div class="requistion-entry-toolbar"><button type="button" data-requistion-full-page aria-pressed="'+requistionEntryWide+'">'+(requistionEntryWide?'↙ Exit Full Page':'⛶ Full Page')+'</button></div><details class="requistion-entry-selection" '+(ready?'':'open')+'><summary>Company / Department / Requistion / Prepared by</summary>'+requistionRequesterPicker()+'</details>'+(ready?requistionNewPaper():'')+(typeof requistionElectricalMenu==='function'?requistionElectricalMenu():'');}
function requistionRowHasData(row){return requistionEntryColumns().some(([key])=>String(row[key]??'').trim());}
function requistionApprovalView(){return requistionNewRows.some(requistionRowHasData)?requistionNewPaper(true):'<section class="requistion-home"><h2>Approval</h2><p>No requisition entries yet.</p></section>';}
$('#main').addEventListener('click',event=>{if(event.target.closest?.('[data-requistion-full-page]')&&document.body.dataset.requistionView==='new-input'&&window.FarnoorAccess?.canPage('requistion-new-input')){requistionEntryWide=!requistionEntryWide;renderRequistion('new-input');$('#main').scrollIntoView?.({block:'start'});}});
function requistionRequesterChange(event,open){const input=event.target;if(!['requistion-request-company','requistion-request-department','requistion-request-requistion','requistion-request-name'].includes(input.id)||document.body.dataset.activeDepartment!=='requistion'||!window.FarnoorAccess?.canPage('requistion-new-input'))return;const key=input.id.replace('requistion-request-','');if(key==='company'&&!requistionCompanies.some(company=>company.name===input.value))return;requistionRequester[key]=String(input.value||'').slice(0,120);if(open)renderRequistion('new-input');else{requistionRequesterShowChoices(key);if(key==='requistion')document.querySelectorAll?.('.requistion-new-title').forEach(node=>node.textContent=requistionRequester.requistion.trim()||'REQUISTION');}}
$('#main').addEventListener('input',event=>requistionRequesterChange(event,false));
$('#main').addEventListener('change',event=>requistionRequesterChange(event,true));

const requistionNewColumns=[['description','DESCRIPTION'],['location','LOCATION'],['size','SIZE'],['qty','QTY'],['unitPrice','UNIT PRICE'],['totalPrice','TOTAL PRICE'],['remarks','REMARKS']];
function requistionIsStore(){return requistionSuggestionKey(requistionRequester.department)==='store';}
function requistionEntryColumns(){return requistionIsStore()?[['description','Item Name'],['location','Required Qty'],['unitPrice','UNIT PRICE'],['totalPrice','TOTAL PRICE'],['remarks','REMARKS']]:requistionNewColumns;}
let requistionNewRows=[{}];
function requistionCurrentDate(){return new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Dhaka',day:'2-digit',month:'2-digit',year:'numeric'}).format(new Date());}
function requistionNewRow(row,index,approval=false){const editable=!approval&&window.FarnoorAccess?.canAction('requistion-new-input','edit')===true,canApprove=approval&&window.FarnoorAccess?.canAction('requistion-approval','edit')===true;return '<tr><td class="requistion-sl">'+(index+1)+'</td>'+requistionEntryColumns().map(([key,label])=>{const control='<input type="text" data-requistion-new-row="'+index+'" data-requistion-new-field="'+key+'" aria-label="'+label+' row '+(index+1)+'" '+(['qty','unitPrice','totalPrice'].includes(key)?'inputmode="decimal" ':'')+'value="'+esc(row[key]||'')+'" '+(editable?'':'readonly')+'>';return '<td>'+(!approval&&key==='description'&&typeof requistionElectricalInput==='function'?requistionElectricalInput(control,index,editable):control)+'</td>';}).join('')+(approval?['accept','reject'].map(mark=>'<td class="requistion-mark-cell"><label class="requistion-mark requistion-mark-'+mark+'"><input type="checkbox" data-requistion-new-row="'+index+'" data-requistion-mark="'+mark+'" aria-label="'+(mark==='accept'?'Green tick':'Red cross')+' row '+(index+1)+'" '+(row.mark===mark?'checked ':'')+(canApprove?'':'disabled')+'><span aria-hidden="true">'+(mark==='accept'?'✓':'✕')+'</span></label></td>').join(''):'')+'</tr>';}
function requistionNewPaper(approval=false){return '<section class="requistion-list-paper requistion-new-paper"><header class="requistion-new-company"><img src="Farnoor_New_Logo.png" alt="Farnoor logo" width="80" height="80"><div><h1>'+esc(requistionCurrentCompany().name)+'</h1><p>'+esc(requistionCurrentCompany().address)+'</p></div></header><p class="requistion-new-date">Date: <time>'+requistionCurrentDate()+'</time></p><h2 class="requistion-new-title">'+esc(requistionRequester.requistion.trim()||'REQUISTION')+'</h2><div class="requistion-request-details"><span><strong>Department:</strong> '+esc(requistionRequester.department.trim())+'</span><span><strong>Prepared by:</strong> '+esc(requistionRequester.name)+'</span></div><div class="requistion-list-scroll"><table class="requistion-list-table requistion-new-table"><colgroup>'+(requistionIsStore()?(approval?[4,29,15,13,13,18,4,4]:[5,35,15,15,15,15]):(approval?[4,25,12,8,7,11,11,14,4,4]:[5,24,13,9,8,13,13,15])).map(width=>'<col style="width:'+width+'%">').join('')+'</colgroup><thead><tr><th rowspan="2" scope="col">SL</th>'+(requistionIsStore()?'<th rowspan="2" scope="col">Item Name</th><th rowspan="2" scope="col">Required Qty</th>':'<th rowspan="2" scope="col">DESCRIPTION</th><th rowspan="2" scope="col">LOCATION</th><th rowspan="2" scope="col">SIZE</th><th rowspan="2" scope="col">QTY</th>')+'<th colspan="2" scope="colgroup">APPRIX RATE</th><th rowspan="2" scope="col">REMARKS</th>'+(approval?'<th rowspan="2" scope="col" class="requistion-mark-accept" aria-label="Green tick">✓</th><th rowspan="2" scope="col" class="requistion-mark-reject" aria-label="Red cross">✕</th>':'')+'</tr><tr><th scope="col">UNIT PRICE</th><th scope="col">TOTAL PRICE</th></tr></thead><tbody id="'+(approval?'requistionApprovalBody':'requistionNewBody')+'">'+requistionNewRows.map((row,index)=>({row,index})).filter(item=>!approval||requistionRowHasData(item.row)).map(item=>requistionNewRow(item.row,item.index,approval)).join('')+'</tbody></table></div><footer class="requistion-signatures">'+['Prepared by','Checked by','Head of Production','General Manager','Managing Director'].map(label=>'<span>'+label+'</span>').join('')+'</footer></section>';}
$('#main').addEventListener('input',event=>{const input=event.target;if(document.body.dataset.requistionView!=='new-input'||!input.matches?.('[data-requistion-new-field]')||!window.FarnoorAccess?.canAction('requistion-new-input','edit'))return;const row=requistionNewRows[Number(input.dataset.requistionNewRow)];if(row){if(row[input.dataset.requistionNewField]!==input.value)row.mark='';row[input.dataset.requistionNewField]=input.value;}});
$('#main').addEventListener('change',event=>{const input=event.target;if(typeof requistionApprovalDraft!=='undefined'&&requistionApprovalDraft&&input.dataset.requistionMark)return;if(document.body.dataset.requistionView!=='approval'||!input.matches?.('[data-requistion-mark]')||!window.FarnoorAccess?.canAction('requistion-approval','edit'))return;const index=Number(input.dataset.requistionNewRow),row=requistionNewRows[index];if(!row)return;row.mark=input.checked?input.dataset.requistionMark:'';document.querySelectorAll('[data-requistion-new-row="'+index+'"][data-requistion-mark]').forEach(box=>box.checked=box.dataset.requistionMark===row.mark);});
$('#main').addEventListener('keydown',event=>{const input=event.target;if(event.defaultPrevented||document.body.dataset.requistionView!=='new-input'||event.key!=='Enter'||event.isComposing||!input.matches?.('[data-requistion-new-field]')||!window.FarnoorAccess?.canAction('requistion-new-input','edit'))return;event.preventDefault();const index=Number(input.dataset.requistionNewRow),row=requistionNewRows[index];if(!row)return;if(row[input.dataset.requistionNewField]!==input.value)row.mark='';row[input.dataset.requistionNewField]=input.value;const next=index+1;if(!requistionNewRows[next]){requistionNewRows.push({});$('#requistionNewBody').insertAdjacentHTML('beforeend',requistionNewRow(requistionNewRows[next],next));}document.querySelector('[data-requistion-new-row="'+next+'"][data-requistion-new-field="description"]')?.focus();});
function renderRequistion(view=''){
 document.body.dataset.requistionView=view;
 const tabs=[['new-input','New Requistion','✚'],['input-report','Requistion List','▤'],['approval','Approval','✓'],['print','Print','▧']].filter(([key])=>window.FarnoorAccess?.canPage('requistion-'+key)),selected=tabs.find(t=>t[0]===view);
 $('#main').innerHTML='<section class="requistion-workspace" data-entry-expanded="'+(view==='new-input'&&requistionEntryWide)+'"><nav class="requistion-tabs" aria-label="Requistion pages">'+tabs.map(([key,label,icon])=>'<button type="button" class="requistion-tab requistion-tab-'+key+'" data-requistion-view="'+key+'" aria-pressed="'+(view===key)+'"><span aria-hidden="true">'+icon+'</span> '+label+'</button>').join('')+'</nav>'+(view==='new-input'?requistionNewView():view==='input-report'?(typeof requistionOutputView==='function'?requistionOutputView('listed'):requistionListPaper()):view==='approval'?requistionApprovalView():view==='print'&&typeof requistionOutputView==='function'?requistionOutputView('print'):'<section class="requistion-home"><span aria-hidden="true">'+(selected?selected[2]:'📋')+'</span><h2>'+(selected?selected[1]:'Requistion')+'</h2></section>')+'</section>';
}
$('#main').addEventListener('click',event=>{const button=event.target.closest('button[data-requistion-view]');if(button&&document.body.dataset.activeDepartment==='requistion')goPage('requistion-'+button.dataset.requistionView);});
$('#navigation').addEventListener('click',event=>{const department=event.target.closest('[data-department]'),page=event.target.closest('[data-page]');if(department){const id=department.dataset.department,wasOpen=opened.has(id);opened.clear();activePage=null;renderClosed();if(!wasOpen)opened.add(id);document.body.dataset.activeDepartment=wasOpen?'':id;if(id==='requistion'&&!wasOpen)renderRequistion();if(id==='sewing-line'&&!wasOpen)$('#main').innerHTML='<section class="account-paper"><h2>Sewing Line</h2></section>';renderNavigation();}if(page){if(activePage===page.dataset.page){activePage=null;renderNavigation();renderClosed();}else goPage(page.dataset.page);}});
function badge(status){return `<span class="badge ${status==='Completed'?'complete':status==='Pending'?'pending':status==='Cancelled'?'cancelled':''}">${esc(status)}</span>`;}
function heading(label,title,subtitle,action=''){return `<div class="page-heading"><div><span class="eyebrow">${esc(label)}</span><h2>${esc(title)}</h2><p>${esc(subtitle)}</p></div>${action}</div>`;}
function allRecords(){return DEPARTMENTS.flatMap(d=>d.pages.flatMap(p=>(state.records[p.id]||[]).map(r=>({...r,page:p.id}))));}
function renderOverview(){
 activePage=null;opened.clear();renderNavigation();const orders=(state.orderFiles||[]).flatMap(file=>file.rows.map(row=>({reference:row.style,name:row.buyer+' · '+row.item,quantity:row.qty,date:row.shipmentDate,status:'Saved'}))),all=allRecords(),pending=all.filter(r=>r.status==='Pending').length;
 $('#main').innerHTML=heading('OPERATIONS OVERVIEW','Your factory, at a glance','A clear view of orders, teams and daily operations.',`<span class="date-tag">${new Date().toLocaleDateString('en-GB',{timeZone:'Asia/Dhaka'})}</span>`)+`<div class="stats">${[['Buyer orders',orders.length,'Saved order rows','#6753ab'],['Order quantity',orders.reduce((s,r)=>s+Number(r.quantity),0).toLocaleString(),'Pieces in the order register','#2d7c95'],['Employee records',(state.records.employees||[]).length,'People in the employee register','#af546d'],['Pending records',pending,'Across all departments','#b17a29']].map(([label,value,note,color])=>`<div class="stat"><span class="accent" style="--accent:${color}"></span><small>${label}</small><strong>${value}</strong><p>${note}</p></div>`).join('')}</div><section class="panel"><div class="panel-header"><h3>Buyer order register</h3><button data-open-page="order-report">View orders</button></div><div class="table-wrap"><table><thead><tr><th>ORDER</th><th>BUYER / STYLE</th><th>QUANTITY</th><th>DELIVERY</th><th>STATUS</th></tr></thead><tbody>${orders.slice(0,5).map(r=>`<tr><td>${esc(r.reference)}</td><td>${esc(r.name)}</td><td>${Number(r.quantity).toLocaleString()} pcs</td><td>${esc(r.date)}</td><td>${badge(r.status)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No orders yet. Open Buyer orders to add one.</td></tr>'}</tbody></table></div></section><div class="overview-bottom"><section class="panel"><div class="panel-header"><h3>Department activity</h3><small>Completed records / total</small></div><div class="progress-list">${DEPARTMENTS.filter(d=>['merch','production','quality'].includes(d.id)).map(d=>{const records=d.pages.flatMap(p=>state.records[p.id]||[]),done=records.filter(r=>r.status==='Completed').length;return `<div><div class="progress-title"><span>${esc(d.name)}</span><strong>${done} / ${records.length}</strong></div><div class="track"><span style="width:${records.length?done/records.length*100:0}%;background:${d.color}"></span></div></div>`;}).join('')}</div></section><section class="panel"><div class="panel-header"><h3>Quick access</h3><small>Common registers</small></div><div class="quick-list"><button data-open-page="order-report">▤ Buyer orders <span>Open</span></button><button data-open-page="store-fabric-receive">▧ Fabric <span>Open</span></button><button data-open-page="employees">♧ Personal File <span>Open</span></button></div></section></div><div class="notice">User workspace · Saved data is stored in the secure online database. Download a backup when needed. Right-click your user profile to edit it; on mobile, tap the profile.</div><p class="footer-note">FARNOOR GARMENTS LTD. · Management workspace · User workspace</p>`;
}
function renderClosed(){$('#main').innerHTML=`<div class="closed"><div class="symbol">▦</div><h2>Page closed</h2><p>Select a page from a department or return to the overview.</p><button id="returnOverview" class="primary">Open overview</button></div>`;}
function fields(){return pageInfo(activePage).page.fields||DEFAULT_FIELDS;}
function filteredRows(){return (state.records[activePage]||[]).filter(r=>(filter==='All statuses'||r.status===filter)&&`${r.reference} ${r.name} ${r.date} ${r.status}`.toLowerCase().includes(query.toLowerCase()));}
function renderRows(){const rows=filteredRows();$('#rows').innerHTML=rows.map(r=>`<tr>${fields().map(([key])=>`<td>${key==='status'?badge(r[key]):esc(key==='quantity'?Number(r[key]).toLocaleString():r[key])}</td>`).join('')}<td><div class="row-actions"><button data-edit="${esc(r.id)}">Edit</button><button data-delete="${esc(r.id)}" aria-label="Delete ${esc(r.reference)}">Delete</button></div></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No matching records. Add a record or adjust your filters.</td></tr>';$('#rowCount').textContent=`${rows.length} of ${(state.records[activePage]||[]).length} records`;}
function renderPage(){const {department,page}=pageInfo(activePage);if(department.id==='requistion')return renderRequistion(page.id.replace('requistion-',''));if(page.navigationOnly){$('#main').innerHTML=heading(department.name,page.name,'')+'<section class="account-paper"><h3>'+esc(page.name)+'</h3></section>';return;}$('#main').innerHTML=heading(department.name,page.name,'Manage your records. Dates are displayed as DD/MM/YYYY.','<button id="newRecord" class="primary">+ New record</button>')+`<section class="panel"><div class="toolbar"><input id="search" type="search" placeholder="Search this register…" aria-label="Search records" value="${esc(query)}"><select id="statusFilter" aria-label="Filter status">${['All statuses',...statuses].map(s=>`<option ${filter===s?'selected':''}>${s}</option>`).join('')}</select><button id="export">Export CSV</button><span id="rowCount" class="count"></span></div><div class="table-wrap"><table><thead><tr>${fields().map(([,label])=>`<th>${esc(label.toUpperCase())}</th>`).join('')}<th>ACTIONS</th></tr></thead><tbody id="rows"></tbody></table></div></section><div class="notice">User workspace · Saved records are stored in the secure online database. Date example: <strong>1/1/26 → 01/01/2026</strong>. Bengali digits are also accepted: <strong>১/১/২৬</strong>.</div>`;renderRows();$('#search').addEventListener('input',e=>{query=e.target.value;renderRows();});$('#statusFilter').addEventListener('change',e=>{filter=e.target.value;renderRows();});}
function openRecord(id=null){editingId=id;const row=(state.records[activePage]||[]).find(r=>r.id===id)||{};$('#recordTitle').textContent=id?'Edit record':'New record';$('#recordCategory').textContent=pageInfo(activePage).page.name;$('#recordFields').innerHTML=fields().map(([key,label,type])=>`<label>${esc(label)}${type==='status'?`<select name="${key}">${statuses.map(s=>`<option ${row[key]===s?'selected':''}>${s}</option>`).join('')}</select>`:`<input name="${key}" ${type==='number'?'type="number" min="0" step="any"':'type="text"'} value="${esc(row[key]??'')}" ${type==='date'?'data-date placeholder="1/1/26" inputmode="numeric"':`maxlength="${key==='name'?200:120}"`} required>`}</label>`).join('');$('#recordDialog').showModal();}
$('#recordForm').addEventListener('focusout',e=>{if(e.target.matches('[data-date]')&&e.target.value){try{e.target.value=normalizeDate(e.target.value);e.target.setCustomValidity('');}catch(error){e.target.setCustomValidity(error.message);}}});
$('#recordForm').addEventListener('input',e=>e.target.setCustomValidity?.(''));
$('#recordForm').addEventListener('submit',async e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));try{values.date=normalizeDate(values.date);}catch(error){toast(error.message);return;}values.reference=values.reference.trim();values.name=values.name.trim();if(!values.reference||!values.name){toast('Reference and description cannot be blank.');return;}values.quantity=Number(values.quantity);values.id=editingId||crypto.randomUUID();const next=structuredClone(state),rows=next.records[activePage]||[];if(editingId)rows[rows.findIndex(r=>r.id===editingId)]=values;else rows.push(values);next.records[activePage]=rows;if(await commit(next)){$('#recordDialog').close();renderPage();toast('Record saved');}});
$('#main').addEventListener('click',async e=>{const target=e.target.closest('button');if(!target)return;if(target.dataset.openPage)goPage(target.dataset.openPage);if(target.id==='returnOverview')renderOverview();if(target.id==='newRecord')openRecord();if(target.dataset.edit)openRecord(target.dataset.edit);if(target.dataset.delete){const id=target.dataset.delete,page=activePage;$('#deleteDialog').showModal();$('#deleteDialog').onclose=async ()=>{if($('#deleteDialog').returnValue==='delete'){const next=structuredClone(state);next.records[page]=next.records[page].filter(r=>r.id!==id);if(await commit(next)){renderPage();toast('Record deleted');}}};}if(target.id==='export')exportCSV();});
function download(filename,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
