'use strict';
const WEEKDAYS=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const BANGLA_MONTHS=['জানুয়ারী','ফেব্রুয়ারী','মার্চ','এপ্রিল','মে','জুন','জুলাই','আগস্ট','সেপ্টেম্বর','অক্টোবর','নভেম্বর','ডিসেম্বর'];
const ENGLISH_MONTHS=['January','February','March','April','May','June','July','August','September','October','November','December'];
const PLAN_FIELDS=[['buyer','BUYER'],['item','ITEM'],['style','STIYLE'],['orderQty','ORDER QTY'],['excess','EXCESS'],['totalQty','TOTAL QTY'],['firstTarget','FAST DAY TERGET'],['dailyTarget','DAILY TERGET'],['startDate','TERGET START DATE'],['remarks','REMARKS']];
function scheduleDigits(value){return String(value).trim().replace(/[০-৯]/g,c=>'০১২৩৪৫৬৭৮৯'.indexOf(c)).replaceAll(',','');}
function parseScheduleMonth(value){let raw=scheduleDigits(value);const named=BANGLA_MONTHS.findIndex(name=>raw.startsWith(name+'-'));if(named>=0)raw=(named+1)+'/'+raw.slice(BANGLA_MONTHS[named].length+1);const english=ENGLISH_MONTHS.findIndex(name=>raw.toLowerCase().startsWith(name.toLowerCase()+'-'));if(english>=0)raw=(english+1)+'/'+raw.slice(ENGLISH_MONTHS[english].length+1);const match=raw.match(/^(\d{1,2})[/-](\d{2}|\d{4})$/);if(!match)throw Error('Month/Year লিখুন যেমন 1/26।');const month=Number(match[1]),year=Number(match[2])+(match[2].length===2?2000:0);if(month<1||month>12||year<1900||year>2199)throw Error('সঠিক Month/Year দিন।');return {month,year,days:new Date(year,month,0).getDate(),label:ENGLISH_MONTHS[month-1]+'-'+year};}
function scheduleInteger(value,label,zero=true){const raw=scheduleDigits(value);if(!/^\d+$/.test(raw)||!Number.isSafeInteger(Number(raw))||Number(raw)>1000000000||(!zero&&Number(raw)===0))throw Error(label+' must be '+(zero?'a non-negative':'a positive')+' whole number.');return Number(raw);}
function excessPercent(row){if(!String(row.orderQty).trim()||!String(row.totalQty).trim())return null;const order=Number(scheduleDigits(row.orderQty)),total=Number(scheduleDigits(row.totalQty));return order>0&&Number.isFinite(total)?(total-order)/order*100:null;}
function signedPercent(value){return value===null||Math.abs(value)<0.005?'':(value>0?'+':'')+Number(value.toFixed(2))+'%';}
function productionDateValue(value){const normalized=normalizeDate(value),[day,month,year]=normalized.split('/').map(Number);return {normalized,time:Date.UTC(year,month-1,day)};}
function productionDateText(time,separator='/'){const date=new Date(time);return [String(date.getUTCDate()).padStart(2,'0'),String(date.getUTCMonth()+1).padStart(2,'0'),date.getUTCFullYear()].join(separator);}
function productionDateRange(draft){const month=parseScheduleMonth(draft.month),start=productionDateValue(draft.rangeStart||`01/${month.month}/${month.year}`),end=productionDateValue(draft.rangeEnd||`${month.days}/${month.month}/${month.year}`);if(end.time<start.time)throw Error('End Date must be on or after Start Date.');if((end.time-start.time)/86400000>365)throw Error('Select a date range of at most 366 days.');return {start,end};}
function productionRangeDays(draft){const range=productionDateRange(draft),days=[];for(let time=range.start.time;time<=range.end.time;time+=86400000)days.push(time);return days;}
function productionIsExtraHoliday(draft,time){const month=parseScheduleMonth(draft.month),date=new Date(time);return (draft.extraDates||[]).includes(productionDateText(time))||(date.getUTCMonth()+1===month.month&&date.getUTCFullYear()===month.year&&(draft.extra||[]).includes(date.getUTCDate()));}
function validateProductionPlan(draft){const month=parseScheduleMonth(draft.month),range=productionDateRange(draft);if(!WEEKDAYS.includes(draft.weekly)&&draft.weekly!=='None')throw Error('Select a weekly holiday.');if(!Array.isArray(draft.extra)||draft.extra.some(day=>!Number.isInteger(day)||day<1||day>month.days))throw Error('Extra holidays must be valid days of the selected month.');if(draft.extraDates!==undefined&&(!Array.isArray(draft.extraDates)||draft.extraDates.length>366))throw Error('Invalid extra holidays.');for(const date of draft.extraDates||[])productionDateValue(date);const rows=draft.rows.filter(row=>Object.values(row).some(value=>String(value).trim())).map(row=>{if(!row.buyer.trim()||!row.item.trim()||!row.style.trim())throw Error('Every filled row needs BUYER, ITEM and STIYLE.');const start=productionDateValue(row.startDate);if(start.time<range.start.time||start.time>range.end.time)throw Error('TERGET START DATE must be inside Start Date and End Date.');return {...row,buyer:row.buyer.trim(),item:row.item.trim(),style:row.style.trim(),remarks:row.remarks.trim(),orderQty:scheduleInteger(row.orderQty,'ORDER QTY',false),totalQty:scheduleInteger(row.totalQty,'TOTAL QTY',false),firstTarget:scheduleInteger(row.firstTarget,'FAST DAY TERGET'),dailyTarget:scheduleInteger(row.dailyTarget,'DAILY TERGET',false),startDate:start.normalized};});if(!rows.length)throw Error('Enter at least one production plan row.');return {...draft,rangeStart:range.start.normalized,rangeEnd:range.end.normalized,rows};}
function generateProductionCalendar(draft){const month=parseScheduleMonth(draft.month),range=productionDateRange(draft),plans=draft.rows.map((row,index)=>{try{const start=productionDateValue(row.startDate);if(start.time<range.start.time||start.time>range.end.time)return null;return {time:start.time,index,key:row.planId||String(index),buyer:row.buyer,style:row.style,remaining:scheduleInteger(row.totalQty,'TOTAL QTY'),first:scheduleInteger(row.firstTarget,'FAST DAY TERGET'),daily:scheduleInteger(row.dailyTarget,'DAILY TERGET'),started:false};}catch{return null;}}).filter(Boolean);const calendar=[];
 for(const time of productionRangeDays(draft)){const day=new Date(time).getUTCDate(),date=productionDateText(time,'-'),weekly=WEEKDAYS[new Date(time).getUTCDay()]===draft.weekly,holiday=productionIsExtraHoliday(draft,time)?'Holiday':weekly?'Weekly Holiday':'';const actual=draft.journal?.[date]||{};let target=0;const allocations=[];if(!holiday)for(const plan of plans){if(time<plan.time||plan.remaining<=0)continue;const override=actual.planTargets?.[plan.key],raw=scheduleDigits(override??''),custom=/^\d+$/.test(raw)&&Number.isSafeInteger(Number(raw))&&Number(raw)<=1000000000;const count=Math.min(plan.remaining,custom?Number(raw):plan.started?plan.daily:plan.first);target+=count;allocations.push({planIndex:plan.index,buyer:plan.buyer,style:plan.style,target:count});plan.remaining-=count;plan.started=true;}const outputEntered=String(actual.output??'').trim()!=='',hoursEntered=String(actual.hours??'').trim()!=='',hours=holiday?0:hoursEntered?Number(actual.hours):10,output=holiday?0:Number(scheduleDigits(actual.output||0));calendar.push({day,date,holiday,target,allocations,hours,output,outputEntered:!holiday&&outputEntered,hoursEntered:!holiday&&hoursEntered,achievement:outputEntered&&target?output/target*100:null,hourlyTarget:allocations.length&&hours>0?target/hours:null,remarks:String(actual.remarks||'')});}
 return {month,calendar,unallocated:plans.reduce((sum,plan)=>sum+plan.remaining,0)};
}
function validateProductionActuals(draft){const result=generateProductionCalendar(draft);for(const row of result.calendar){if(row.holiday)continue;const actual=draft.journal?.[row.date]||{};scheduleInteger(actual.output||'0','DAILY OUTPUT');if(actual.planTargets!==undefined){if(!actual.planTargets||typeof actual.planTargets!=='object'||Array.isArray(actual.planTargets)||Object.keys(actual.planTargets).length>10000)throw Error('Invalid daily targets.');for(const value of Object.values(actual.planTargets))scheduleInteger(value,'DAILY TERGET');for(const entry of row.allocations){const key=draft.rows[entry.planIndex]?.planId||String(entry.planIndex),value=actual.planTargets[key];if(value!==undefined&&scheduleInteger(value,'DAILY TERGET')>entry.target)throw Error('DAILY TERGET exceeds remaining TOTAL QTY on '+row.date);}}const hours=Number(actual.hours??10);if(!Number.isFinite(hours)||hours<=0||hours>24)throw Error('TOTAL HOURS must be greater than 0 and at most 24.');if(String(actual.remarks||'').length>500)throw Error('Daily remarks are too long.');}return result;}

