function adminSignChooseName(value){const record=adminSignRecords.find(row=>adminSignKey(row.fullName)===adminSignKey(value));if(record)adminSignOpenRecord(record);else adminSignDraft.fullName=value;}
function adminSignPhotosHTML(){return adminSignDraft.photos.map(photo=>'<figure><img src="'+esc(photo.data)+'" alt="'+esc(photo.name)+'"><figcaption>'+esc(photo.name)+'</figcaption><button type="button" data-sign-remove-photo="'+esc(photo.id)+'" aria-label="Remove '+esc(photo.name)+'">×</button></figure>').join('');}
function adminSignTable(){return '<div class="table-wrap admin-sign-table-wrap"><table class="admin-sign-table"><thead><tr><th scope="col">SL</th><th scope="col">Full Name</th><th scope="col">ID No</th><th scope="col">Sign Photo</th></tr></thead><tbody>'+adminSignRecords.map((row,index)=>'<tr data-sign-record="'+esc(row.id)+'"'+(row.id===adminSignDraft.id?' class="admin-sign-selected"':'')+'><td>'+(index+1)+'</td><td><button type="button" class="admin-sign-open" data-sign-open="'+esc(row.id)+'">'+esc(row.fullName)+'</button></td><td>'+esc(row.idNo)+'</td><td><div class="admin-sign-table-photos">'+row.photos.map(photo=>'<img src="'+esc(photo.data)+'" alt="'+esc(row.fullName+' — '+photo.name)+'" loading="lazy">').join('')+'</div><button type="button" class="admin-sign-delete" data-sign-delete="'+esc(row.id)+'">Delete</button></td></tr>').join('')+(!adminSignRecords.length?'<tr><td colspan="4" class="empty">No saved Sign</td></tr>':'')+'</tbody></table></div>';}
function renderAdminSign(){if(accessInfo.role!=='super_admin')return;$('#main').insertAdjacentHTML('beforeend','<section class="panel admin-sign-panel"><h3>✍ Sign</h3><form id="adminSignForm"><fieldset '+(adminSignBusy||adminSignLoading?'disabled':'')+'><label for="adminSignFullName">Full Name</label><div class="admin-sign-name"><input id="adminSignFullName" name="fullName" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="adminSignNames" autocomplete="off" placeholder="Type 2 characters or enter a new name" maxlength="200" value="'+esc(adminSignDraft.fullName)+'" required><button type="button" data-sign-names aria-label="Show Full Name list">▾</button><div id="adminSignNames" role="listbox" hidden></div></div><label for="adminSignIdNo">ID NO</label><input id="adminSignIdNo" name="idNo" maxlength="120" value="'+esc(adminSignDraft.idNo)+'"><div class="admin-sign-actions"><button type="button" id="adminSignPhoto" class="admin-sign-photo-button">▣ Sign Photo</button><input type="file" id="adminSignPhotoFiles" accept="image/png,image/jpeg,image/webp" multiple hidden></div><div id="adminSignPhotos" class="admin-sign-photos">'+adminSignPhotosHTML()+'</div><p id="adminSignStatus" role="status">'+esc(adminSignError||(adminSignLoading?'Loading saved Sign…':''))+'</p><div class="admin-sign-actions"><button type="submit" class="primary" '+(adminSignBusy?'disabled':'')+'>Save</button><button type="button" data-sign-new>+ New Sign</button></div></fieldset></form><div class="admin-sign-saved"><h4>Saved Sign <button type="button" data-sign-refresh>Refresh</button></h4>'+adminSignTable()+'</div></section>');}
function adminSignShowNames(all=false){const input=$('#adminSignFullName'),menu=$('#adminSignNames');if(!input||!menu)return;const names=adminSignNames(input.value,all);adminSignMenuIndex=-1;menu.innerHTML=names.map(name=>'<button type="button" role="option" tabindex="-1" data-sign-name="'+esc(name)+'">'+esc(name)+'</button>').join('');menu.hidden=!names.length;input.setAttribute('aria-expanded',String(!!names.length));input.removeAttribute('aria-activedescendant');}
function adminSignCloseNames(){const menu=$('#adminSignNames'),input=$('#adminSignFullName');if(menu)menu.hidden=true;if(input){input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');}adminSignMenuIndex=-1;}
function adminSignCommitName(value){adminSignChooseName(value);const input=$('#adminSignFullName'),id=$('#adminSignIdNo');if(input)input.value=adminSignDraft.fullName;if(id)id.value=adminSignDraft.idNo;adminSignRefreshPhotos();adminSignCloseNames();const table=document.querySelector('.admin-sign-table-wrap');if(table)table.outerHTML=adminSignTable();}
function adminSignRefreshPhotos(){const gallery=$('#adminSignPhotos');if(gallery)gallery.innerHTML=adminSignPhotosHTML();}
async function adminSignReadPhoto(file){
 if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>10000000)throw Error('১০ MB-এর মধ্যে PNG, JPG বা WebP ছবি দিন।');
 const url=URL.createObjectURL(file);try{const image=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('ছবিটি খোলা যায়নি। অন্য ছবি বেছে নিন।'));img.src=url;});let data='';for(const limit of [1600,1000,700]){const ratio=Math.min(1,limit/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*ratio));canvas.height=Math.max(1,Math.round(image.naturalHeight*ratio));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);data=canvas.toDataURL('image/png');if(data.length<=1400000)break;}const photo={id:crypto.randomUUID(),name:String(file.name||'Sign Photo').slice(0,200),data};validateAdminSignatures([{id:'preview',fullName:'Preview',idNo:'',photos:[photo]}]);return photo;}finally{URL.revokeObjectURL(url);}
}
async function loadAdminSign(){if(accessInfo.role!=='super_admin'||adminSignLoading||adminSignBusy)return;adminSignLoading=true;adminSignError='';if(adminView&&adminUserPanel==='sign')renderAdminView();try{const result=await adminRequest('signs');validateAdminSignatures(result.files);adminSignRecords=result.files;adminSignLoaded=true;}catch(error){adminSignError=error.message;toast(error.message);}finally{adminSignLoading=false;if(adminView&&adminUserPanel==='sign')renderAdminView();}}
async function saveAdminSign(){
 if(accessInfo.role!=='super_admin'||adminSignBusy)return false;adminSignBusy=true;
 const status=$('#adminSignStatus'),fieldset=$('#adminSignForm')?.querySelector('fieldset');if(fieldset)fieldset.disabled=true;
 try{const file={...structuredClone(adminSignDraft),id:adminSignDraft.id||crypto.randomUUID(),fullName:adminSignDraft.fullName.trim().replace(/\s+/g,' '),idNo:adminSignDraft.idNo.trim()},rows=adminSignRecords.slice(),index=rows.findIndex(row=>row.id===file.id);
  if(adminSignDraft.id&&(index<0||JSON.stringify(rows[index])!==adminSignOriginal))throw Error('এই Sign অন্য জায়গা থেকে বদলেছে। লেখা রাখা আছে; সর্বশেষ তথ্য মিলিয়ে নিন।');
  if(index>=0)rows[index]=file;else rows.push(file);validateAdminSignatures(rows);const result=await adminRequest('signs',{method:'POST',body:JSON.stringify({file,revision:adminSignDraft.revision||0})});validateAdminSignatures([result.file]);if(result.file.id!==file.id)throw Error('Save নিশ্চিত হয়নি। লেখা রাখা আছে।');if(index>=0)adminSignRecords[index]=result.file;else adminSignRecords.push(result.file);adminSignOpenRecord(result.file);if(adminView&&adminUserPanel==='sign')renderAdminView();toast('Sign saved online');return true;
 }catch(error){if(status)status.textContent=error.message;return false;}finally{adminSignBusy=false;const fieldset=$('#adminSignForm')?.querySelector('fieldset');if(fieldset)fieldset.disabled=false;}
}
async function deleteAdminSign(id){if(accessInfo.role!=='super_admin'||adminSignBusy)return false;const row=adminSignRecords.find(row=>row.id===id);if(!row||!window.confirm('Delete Sign: '+row.fullName+' ('+row.idNo+')?'))return false;adminSignBusy=true;try{const result=await adminRequest('signs',{method:'DELETE',body:JSON.stringify({id:row.id,revision:row.revision})});if(result.deletedId!==row.id)throw Error('Delete was not confirmed.');adminSignRecords=adminSignRecords.filter(item=>item.id!==id);if(adminSignDraft.id===id){adminSignDraft={id:'',fullName:'',idNo:'',photos:[]};adminSignOriginal=null;}if(adminView&&adminUserPanel==='sign')renderAdminView();toast('Sign deleted');return true;}catch(error){toast(error.message);return false;}finally{adminSignBusy=false;}}
// Select before blur/change can close the list, for both mouse and touch pointers.
$('#main').addEventListener('pointerdown',event=>{if(!adminView||adminUserPanel!=='sign'||accessInfo.role!=='super_admin'||adminSignBusy)return;const choice=event.target.closest('[data-sign-name]');if(choice){event.preventDefault();event.stopImmediatePropagation();adminSignCommitName(choice.dataset.signName);}},true);
$('#main').addEventListener('mousedown',event=>{if(adminView&&adminUserPanel==='sign'&&event.target.closest('[data-sign-name],[data-sign-names]'))event.preventDefault();});
$('#main').addEventListener('input',event=>{if(!adminView||adminUserPanel!=='sign'||accessInfo.role!=='super_admin')return;if(event.target.id==='adminSignFullName'){adminSignDraft.fullName=event.target.value;adminSignShowNames();}if(event.target.id==='adminSignIdNo')adminSignDraft.idNo=event.target.value;});
$('#main').addEventListener('change',async event=>{
 if(!adminView||adminUserPanel!=='sign'||accessInfo.role!=='super_admin')return;
 if(event.target.id==='adminSignFullName')adminSignCommitName(event.target.value);
 if(event.target.id!=='adminSignPhotoFiles')return;const input=event.target,files=[...input.files],status=$('#adminSignStatus');if(!files.length)return;if(adminSignBusy){input.value='';return;}adminSignBusy=true;const button=$('#adminSignPhoto');button.disabled=true;const fieldset=$('#adminSignForm')?.querySelector('fieldset');if(fieldset)fieldset.disabled=true;status.textContent='ছবি লোড হচ্ছে…';try{if(adminSignDraft.photos.length+files.length>20)throw Error('একটি Sign-এ সর্বোচ্চ ২০টি ছবি রাখা যাবে।');const added=[];for(const file of files)added.push(await adminSignReadPhoto(file));const photos=[...adminSignDraft.photos,...added];validateAdminSignatures([{...adminSignDraft,id:adminSignDraft.id||'preview',fullName:adminSignDraft.fullName||'Preview',photos}]);adminSignDraft.photos=photos;if(adminView&&adminUserPanel==='sign'){adminSignRefreshPhotos();$('#adminSignStatus').textContent='ছবি লোড হয়েছে। রাখতে Save চাপুন।';}}catch(error){if(adminView&&adminUserPanel==='sign')$('#adminSignStatus').textContent=error.message;}finally{adminSignBusy=false;button.disabled=false;input.value='';const fieldset=$('#adminSignForm')?.querySelector('fieldset');if(fieldset)fieldset.disabled=false;}
});
$('#main').addEventListener('click',event=>{
 if(!adminView||accessInfo.role!=='super_admin')return;const button=event.target.closest('button');if(!button)return;
 if(button.id==='adminSign'){adminUserPanel=adminUserPanel==='sign'?'':'sign';departmentPanelOpen=false;renderAdminView();if(adminUserPanel==='sign'&&!adminSignLoaded)void loadAdminSign();return;}
 if(adminUserPanel!=='sign'||adminSignBusy)return;
 if(button.hasAttribute('data-sign-refresh')){void loadAdminSign();return;}
 if(button.hasAttribute('data-sign-names')){adminSignShowNames(true);return;}
 if(button.dataset.signName){adminSignCommitName(button.dataset.signName);return;}
 if(button.id==='adminSignPhoto'){$('#adminSignPhotoFiles').click();return;}
 if(button.hasAttribute('data-sign-new')){adminSignDraft={id:'',fullName:'',idNo:'',photos:[]};adminSignOriginal=null;renderAdminView();return;}
 if(button.dataset.signDelete){void deleteAdminSign(button.dataset.signDelete);return;}
 if(button.dataset.signOpen){const record=adminSignRecords.find(row=>row.id===button.dataset.signOpen);if(record){adminSignOpenRecord(record);renderAdminView();$('#adminSignFullName')?.focus();$('#adminSignFullName')?.select?.();}return;}
 if(button.dataset.signRemovePhoto){adminSignDraft.photos=adminSignDraft.photos.filter(photo=>photo.id!==button.dataset.signRemovePhoto);adminSignRefreshPhotos();return;}
 if(!event.target.closest('.admin-sign-name'))adminSignCloseNames();
});
$('#main').addEventListener('keydown',event=>{if(!adminView||adminUserPanel!=='sign'||event.target.id!=='adminSignFullName')return;const menu=$('#adminSignNames');if(event.key==='Escape'){adminSignCloseNames();return;}if(!['ArrowDown','ArrowUp','Enter'].includes(event.key))return;if(menu.hidden&&event.key!=='Enter')adminSignShowNames(true);const options=[...menu.querySelectorAll('[data-sign-name]')];if(!options.length||menu.hidden)return;event.preventDefault();if(event.key==='Enter'){if(adminSignMenuIndex>=0||options.length===1)adminSignCommitName(options[Math.max(0,adminSignMenuIndex)].dataset.signName);return;}adminSignMenuIndex=adminSignMenuIndex<0?(event.key==='ArrowDown'?0:options.length-1):(adminSignMenuIndex+(event.key==='ArrowDown'?1:-1)+options.length)%options.length;options.forEach((option,index)=>{option.id='admin-sign-name-'+index;option.setAttribute('aria-selected',String(index===adminSignMenuIndex));});event.target.setAttribute('aria-activedescendant',options[adminSignMenuIndex].id);options[adminSignMenuIndex].scrollIntoView({block:'nearest'});});
$('#main').addEventListener('submit',event=>{if(event.target.id!=='adminSignForm')return;event.preventDefault();if(accessInfo.role==='super_admin')void saveAdminSign();});

