const warningDocumentPages={'admin-warning-first-letter':['1st Letter',1],'admin-warning-second-letter':['2nd Letter',2],'admin-warning-third-letter':['3rd Letter',3],'admin-warning-envelope-1':['Envelope1',4],'admin-warning-envelope-2':['Envelope2',5]};
function warningDocumentBn(value){return String(value??'').replace(/[0-9]/g,d=>'০১২৩৪৫৬৭৮৯'[d]);}
function warningDocumentDate(value){return esc(warningDocumentBn(value).replaceAll('/','.'));}
function warningDocumentValue(value){return '<span class="wd-value">'+esc(value||'')+'</span>';}
