function warningDocumentPairs(pairs){return '<div class="wd-pairs">'+pairs.map(([label,value])=>'<div>'+esc(label)+'</div><div>'+(label?':':'')+'</div><div>'+warningDocumentValue(value)+'</div>').join('')+'</div>';}
function warningDocumentCompany(){return warningHomeCompany.includes('UNIT-2')?{name:'ফারনূর গার্মেন্টস লিঃ-ইউনিট-২',address:'৪৫৪, বাবুরচালা, পিরুজালী, আলীমপাড়া, গাজীপুর সদর, গাজীপুর'}:{name:'ফারনূর গার্মেন্টস লিঃ',address:'১২০৮/১/২ মালিবাগ বাজার রোড, ঢাকা-১২১৭'};}
