function warningDocumentSelection(){return warningSavedRowForCard(warningHomeCard);}
function renderWarningDocument(){const [title,kind]=warningDocumentPages[activePage],row=warningDocumentSelection(),bangla=warningBanglaEntry(row?.warningBenefitEntry||{}),message=row?warningBanglaStatus(bangla):'',page=activePage,card=warningHomeCard;if(row&&!warningBanglaHrCache.has(adminHrLookupKey(card)))void warningBanglaLoad(card).then(()=>{if(activePage===page&&adminHrLookupKey(card)===adminHrLookupKey(warningHomeCard))renderPage();});document.getElementById('main').innerHTML='<style>'+warningDocumentCSS+'</style><div class="wd-document-toolbar no-print"><h2>'+title+(kind<4?' · A4':' · 6.25 × 3.625 in')+'</h2><button type="button" class="primary" data-warning-document-print>Print</button></div>'+(!row?'<div class="wd-missing no-print">Warning Letter পেইজে Card No. দিয়ে Save চাপুন। তারপর এই ফাইলে সেভ করা তথ্য দেখাবে।</div>':'')+(message?'<div class="wd-missing no-print">'+esc(message)+'</div>':'')+'<section class="wd-preview">'+warningDocumentPaper(row?.warningBenefitEntry,kind)+'</section>';}
const warningDocumentPreviousRender=renderPage;renderPage=function(...args){if(!warningDocumentPages[activePage])return warningDocumentPreviousRender.apply(this,args);renderWarningDocument();const nav=document.createElement('nav');nav.className='no-print';nav.setAttribute('aria-label','Warning Letter pages');nav.style.cssText='display:flex;flex-wrap:wrap;gap:9px;margin-bottom:20px';nav.innerHTML=[['admin-warning-new-entry','✚ New Input'],...Object.entries(warningDocumentPages).map(([id,[title]])=>[id,title]),['admin-warning-entry-report','▤ Entry Report']].filter(([id])=>FarnoorAccess.canPage(id)).map(([id,title])=>'<button type="button" data-warning-top="'+id+'" aria-current="'+(id===activePage?'page':'false')+'">'+title+'</button>').join('');document.getElementById('main').prepend(nav);};
document.getElementById('main').addEventListener('click',event=>{if(!event.target.closest('[data-warning-document-print]'))return;event.preventDefault();event.stopImmediatePropagation();if(!warningDocumentSelection())return toast('প্রথমে Warning Letter পেইজে সেভ করা Card No. নির্বাচন করুন।');const missing=warningBanglaStatus(warningBanglaEntry(warningDocumentSelection().warningBenefitEntry));if(missing)return toast(missing);const title=warningDocumentPages[activePage][0],old=document.title;document.title=title;window.addEventListener('afterprint',()=>{document.title=old;},{once:true});window.print();},true);

