 $('#main').innerHTML='<div class="hourly-pd-workspace"><nav class="hourly-pd-nav no-print" aria-label="Line Wise Hourly PD pages">'+nav.map(([key,icon,name])=>'<button type="button" data-hourly-pd-view="'+key+'" class="hourly-pd-'+key+'" aria-pressed="'+(hourlyPDView===key)+'"><span aria-hidden="true">'+icon+'</span> '+name+'</button>').join('')+'</nav>'+(hourlyPDView==='input-report'?hourlyPDReport():hourlyPDView==='print'?hourlyPDPrintView():hourlyPDPaper())+'</div>';
 if(typeof applyActionControls==='function')applyActionControls();
