 if(button){hourlyPDView=button.dataset.hourlyPdView;if(hourlyPDView==='new-input'&&hourlyPDEditId){hourlyPDDraft.fields={};hourlyPDDraft.rows=hourlyPDHours.map(()=>Array(5).fill(''));for(const key of ['targets','differences','achievements'])hourlyPDDraft[key]=Array(5).fill('');hourlyPDEditId=null;hourlyPDPendingId=null;}if(hourlyPDView==='print'){hourlyPDSelectedId=null;hourlyPDPrintDate||=hourlyPDToday();}renderHourlyPD();return;}
