function ironPDCompare(a,b){const dates=String(b.date).split('/').reverse().join('-').localeCompare(String(a.date).split('/').reverse().join('-'));const as=ironPDNumber(a.hourlyPD.fields?.sl),bs=ironPDNumber(b.hourlyPD.fields?.sl);return dates||(as!==null&&bs!==null?as-bs:0)||ironPDTable(a.hourlyPD.fields).localeCompare(ironPDTable(b.hourlyPD.fields),undefined,{numeric:true,sensitivity:'base'});}
