 if(!name||name.length>120||!card||card.length>40||!['SAMPLE-1','SAMPLE-2'].includes(section)||!Number.isInteger(sl)||sl<1||sl>999)throw Error('Section নির্বাচন করে সঠিক নাম ও Card No লিখুন।');
