'use strict';
// Use the same configured 2026 general/executive holidays as Warning Letter.
const requistionCalendarHolidays=new Set(["2026-02-04","2026-02-21","2026-03-17","2026-03-18","2026-03-19","2026-03-20","2026-03-21","2026-03-22","2026-03-23","2026-03-26","2026-04-14","2026-05-01","2026-05-26","2026-05-27","2026-05-28","2026-05-29","2026-05-30","2026-05-31","2026-06-26","2026-08-05","2026-08-26","2026-09-04","2026-10-20","2026-10-21","2026-12-16","2026-12-25"]);
function requistionCalendarDate(value){const raw=String(value||'').replace(/[০-৯]/g,c=>'০১২৩৪৫৬৭৮৯'.indexOf(c)).trim(),iso=/^\d{4}-\d{2}-\d{2}$/.test(raw)?raw:raw.split(/[/.\-]/).reverse().map((value,index)=>index?value.padStart(2,'0'):value.length===2?'20'+value:value).join('-'),date=new Date(iso+'T00:00:00Z');if(!/^\d{4}-\d{2}-\d{2}$/.test(iso)||!Number.isFinite(date.getTime())||date.toISOString().slice(0,10)!==iso)throw Error('Invalid calendar date.');return date;}
function requistionExtraHolidayDates(records){const dates=new Set();for(const row of records||[]){if(row.deletedAt)continue;const d=row.hrDetails||{};try{const from=requistionCalendarDate(d.date||d.Date||row.date),to=d.date_end_year&&d.date_end_month&&d.date_end_day?requistionCalendarDate(d.date_end_year+'-'+String(d.date_end_month).padStart(2,'0')+'-'+String(d.date_end_day).padStart(2,'0')):from;for(let date=new Date(from),i=0;date<=to&&i<366;i++,date.setUTCDate(date.getUTCDate()+1))dates.add(date.toISOString().slice(0,10));}catch{}}return dates;}
