async function requistionOpenSaved(id){const result=await requistionWorkflowRequest('files','GET',{id});if(result.file.stage&&result.file.stage!=='approval'){const stage=result.file.stage,page=stage==='print'?'requistion-print':'requistion-input-report';requistionOutputState[stage].selected=structuredClone(result.file);requistionOutputState[stage].loaded=false;requistionApprovalDraft=null;if(window.FarnoorAccess.canPage(page))goPage(page);return result.file;}requistionApprovalDraft=structuredClone(result.file);requistionApprovalDraft.signatures=Array.from({length:5},(_,index)=>requistionApprovalDraft.signatures[index]||null);requistionWorkflowError='';if(document.body.dataset.activeDepartment==='requistion'&&document.body.dataset.requistionView==='approval')renderRequistion('approval');return result.file;}
requistionApprovalView=function(){if(!requistionSavedLoaded&&!requistionSavedLoading&&!requistionWorkflowError)setTimeout(()=>requistionLoadFiles(),0);return '<section class="requistion-approval-files no-print"><div class="requistion-approval-file-heading"><h3>Saved Requistions</h3><button type="button" data-requistion-files-refresh '+(requistionWorkflowBusy||requistionSavedLoading?'disabled':'')+'>Refresh</button></div><p role="status">'+esc(requistionSavedLoading?'Loading…':requistionWorkflowError)+'</p><div class="requistion-saved-file-list">'+requistionSavedFiles.map(file=>'<button type="button" data-requistion-file-open="'+esc(file.id)+'" aria-pressed="'+(requistionApprovalDraft?.id===file.id)+'" '+(requistionWorkflowBusy?'disabled':'')+'>'+esc(file.date)+' · '+esc(file.requester.department)+' · '+esc(file.requester.requistion||'Requistion')+' · '+esc(file.requester.name)+'</button>').join('')+(!requistionSavedFiles.length&&!requistionSavedLoading?'<p>New Requistion থেকে Save করা ফাইল এখানে থাকবে।</p>':'')+'</div>'+(requistionSavedFiles.length<requistionSavedTotal?'<button type="button" data-requistion-files-more>Load more</button>':'')+'</section>'+(requistionApprovalDraft?requistionWithSavedFile(requistionApprovalDraft,()=>requistionNewPaper(true))+'<div class="requistion-save-actions no-print"><button type="button" class="primary" data-requistion-approval-save '+(requistionWorkflowBusy||!window.FarnoorAccess.canAction('requistion-approval','edit')?'disabled':'')+'>'+(requistionWorkflowBusy?'Saving…':'Save Approval')+'</button></div>':'');};
async function saveRequistionFile(){if(requistionWorkflowBusy||!window.FarnoorAccess.canAction('requistion-new-input','edit'))return false;const rows=requistionNewRows.filter(requistionRowHasData).map(row=>({...row}));if(!requistionRequesterReady()||!rows.length){toast('Department, Prepared by ও টেবিলের তথ্য দিন।');return false;}requistionDraftIdentity||={id:crypto.randomUUID(),revision:0};requistionWorkflowBusy=true;requistionWorkflowError='';renderRequistion('new-input');try{const result=await requistionWorkflowRequest('files','POST',{...requistionDraftIdentity,action:'input',requester:{...requistionRequester},rows});requistionDraftIdentity={id:result.file.id,revision:result.file.revision};requistionApprovalDraft=structuredClone(result.file);requistionApprovalDraft.signatures=Array(5).fill(null);requistionSavedLoaded=false;requistionWorkflowBusy=false;toast('Requistion সেভ হয়েছে।');if(document.body.dataset.activeDepartment==='requistion'&&document.body.dataset.requistionView==='new-input'){if(window.FarnoorAccess.canPage('requistion-approval'))goPage('requistion-approval');else renderRequistion('new-input');}return true;}catch(error){requistionWorkflowError=error.message;toast(error.message);return false;}finally{requistionWorkflowBusy=false;if(document.body.dataset.activeDepartment==='requistion')renderRequistion(document.body.dataset.requistionView);}}
async function requistionLookupSign(index){if(!requistionApprovalDraft||requistionWorkflowBusy||!window.FarnoorAccess.canAction('requistion-approval','edit'))return;const file=requistionApprovalDraft,id=file.id,slot=file.signatures[index],query=slot?.query?.trim()||'',serial=(requistionLookupSerial.get(index)||0)+1;requistionLookupSerial.set(index,serial);if(!query)return;try{const {sign}=await requistionWorkflowRequest('signature','GET',{query});if(requistionApprovalDraft?.id!==id||requistionLookupSerial.get(index)!==serial||requistionApprovalDraft.signatures[index]?.query.trim()!==query)return;if(!sign.photos.length)throw Error('এই নামে Sign Photo নেই।');const selected=sign.photos[0];file.signatures[index]={query,signId:sign.id,fullName:sign.fullName,idNo:sign.idNo,photoId:selected.id,photo:selected,photos:sign.photos};}catch(error){if(requistionApprovalDraft?.id!==id||requistionLookupSerial.get(index)!==serial)return;file.signatures[index]={query,error:error.message};}if(document.body.dataset.requistionView==='approval'){const preview=document.querySelector('[data-requistion-sign-preview="'+index+'"]');if(preview)preview.innerHTML=requistionSignPreview(file.signatures[index],requistionSignatureLabels[index],index);}}
async function saveRequistionApproval(){if(!requistionApprovalDraft||requistionWorkflowBusy||!window.FarnoorAccess.canAction('requistion-approval','edit'))return false;const file=requistionApprovalDraft;if(file.signatures.length!==5||file.signatures.some(slot=>!slot?.signId||!slot.photoId)){toast('পাঁচটি স্বাক্ষরের ঘর পূরণ করার পর Save Approval চাপুন।');return false;}requistionWorkflowBusy=true;renderRequistion('approval');try{const result=await requistionWorkflowRequest('files','POST',{id:file.id,revision:file.revision,action:'approval',marks:file.rows.map(row=>row.mark||''),signatures:file.signatures.map(slot=>slot?.signId?{signId:slot.signId,photoId:slot.photoId,query:slot.query}:null)});requistionApprovalDraft=structuredClone(result.file);requistionApprovalDraft.signatures=Array.from({length:5},(_,i)=>result.file.signatures[i]||null);requistionSavedLoaded=false;requistionOutputState.print.loaded=false;requistionOutputState.print.selected=structuredClone(result.file);requistionApprovalDraft=null;toast('Approval সেভ হয়েছে। ফাইল Print পেইজে আছে।');if(document.body.dataset.activeDepartment==='requistion'&&document.body.dataset.requistionView==='approval'&&window.FarnoorAccess.canPage('requistion-print'))goPage('requistion-print');return true;}catch(error){requistionWorkflowError=error.message;toast(error.message);return false;}finally{requistionWorkflowBusy=false;if(document.body.dataset.activeDepartment==='requistion'&&document.body.dataset.requistionView==='approval')renderRequistion('approval');}}
$('#main').addEventListener('change',event=>{const input=event.target;if(document.body.dataset.requistionView!=='approval'||!requistionApprovalDraft||requistionWorkflowBusy||!window.FarnoorAccess.canAction('requistion-approval','edit'))return;if(input.dataset.requistionMark){const row=requistionApprovalDraft.rows[Number(input.dataset.requistionNewRow)];if(row){row.mark=input.checked?input.dataset.requistionMark:'';requistionApprovalDraft.dirty=true;document.querySelectorAll('[data-requistion-new-row="'+input.dataset.requistionNewRow+'"][data-requistion-mark]').forEach(box=>box.checked=box.dataset.requistionMark===row.mark);}}if(input.dataset.requistionSignPhoto!==undefined){const index=Number(input.dataset.requistionSignPhoto),slot=requistionApprovalDraft.signatures[index],photo=slot?.photos?.find(photo=>photo.id===input.value);if(photo){slot.photoId=photo.id;slot.photo=photo;requistionApprovalDraft.dirty=true;document.querySelector('[data-requistion-sign-preview="'+index+'"]').innerHTML=requistionSignPreview(slot,requistionSignatureLabels[index],index);}}});
$('#main').addEventListener('input',event=>{const input=event.target;if(input.dataset.requistionSignQuery===undefined||document.body.dataset.requistionView!=='approval'||!requistionApprovalDraft||requistionWorkflowBusy||!window.FarnoorAccess.canAction('requistion-approval','edit'))return;const index=Number(input.dataset.requistionSignQuery);requistionApprovalDraft.signatures[index]={query:input.value};requistionApprovalDraft.dirty=true;requistionLookupSerial.set(index,(requistionLookupSerial.get(index)||0)+1);const preview=document.querySelector('[data-requistion-sign-preview="'+index+'"]');if(preview)preview.innerHTML='';clearTimeout(requistionLookupTimers.get(index));requistionLookupTimers.set(index,setTimeout(()=>requistionLookupSign(index),400));});
$('#main').addEventListener('keydown',event=>{if(event.target.dataset.requistionSignQuery!==undefined&&event.key==='Enter'){event.preventDefault();clearTimeout(requistionLookupTimers.get(Number(event.target.dataset.requistionSignQuery)));void requistionLookupSign(Number(event.target.dataset.requistionSignQuery));}});
$('#main').addEventListener('click',async event=>{if(document.body.dataset.activeDepartment!=='requistion')return;const button=event.target.closest('button');if(!button||requistionWorkflowBusy)return;if(button.hasAttribute('data-requistion-new-file')){if(!window.FarnoorAccess.canAction('requistion-new-input','edit'))return;if(requistionNewRows.some(requistionRowHasData)&&!window.confirm('Start a new file? Save the current entries first.'))return;requistionNewRows=[{}];requistionDraftIdentity=null;requistionWorkflowError='';renderRequistion('new-input');return;}if(button.hasAttribute('data-requistion-save'))return void saveRequistionFile();if(button.hasAttribute('data-requistion-approval-save'))return void saveRequistionApproval();if(button.hasAttribute('data-requistion-files-refresh'))return void requistionLoadFiles();if(button.hasAttribute('data-requistion-files-more'))return void requistionLoadFiles(true);if(button.dataset.requistionSignSearch!==undefined)return void requistionLookupSign(Number(button.dataset.requistionSignSearch));if(button.dataset.requistionFileOpen){if(requistionApprovalDraft?.dirty&&!window.confirm('Discard unsaved approval changes?'))return;button.disabled=true;try{await requistionOpenSaved(button.dataset.requistionFileOpen);}catch(error){toast(error.message);button.disabled=false;}}});

// Saved files change lists automatically on their stored third-working-day date.
const requistionOutputState={print:{files:[],total:0,loaded:false,loading:false,error:'',selected:null},listed:{files:[],total:0,loaded:false,loading:false,error:'',selected:null}};
function requistionOutputStage(){return document.body.dataset.requistionView==='print'?'print':document.body.dataset.requistionView==='input-report'?'listed':null;}
function requistionOutputSignatures(file){return '<footer class="requistion-signatures requistion-approval-signatures">'+requistionSignatureLabels.map((label,index)=>{const sign=file.signatures?.[index];return '<section class="requistion-sign-slot"><div class="requistion-sign-preview">'+(sign?.photo?'<img src="'+esc(sign.photo.data)+'" alt="'+esc(label+' — '+sign.fullName)+'"><small>'+esc(sign.fullName)+'</small>':'')+'</div><div class="requistion-sign-label">'+label+'</div></section>';}).join('')+'</footer>';}
function requistionOutputPaper(file){return requistionWithSavedFile(file,()=>requistionWorkflowBasePaper(false).replace(/<footer class="requistion-signatures">[\s\S]*?<\/footer>/,requistionOutputSignatures(file)).replace(/<input /g,'<input readonly '));}
async function requistionLoadOutput(stage,more=false){const state=requistionOutputState[stage];if(!state||state.loading)return;state.loading=true;state.error='';try{const result=await requistionWorkflowRequest('files','GET',{stage,offset:more?state.files.length:0});state.files=more?[...state.files,...result.files]:result.files;state.total=result.total;state.loaded=true;if(state.selected){const latest=(await requistionWorkflowRequest('files','GET',{id:state.selected.id})).file;if(latest.stage!==stage)state.selected=null;else state.selected=latest;}if(!state.selected&&state.files.length){const first=(await requistionWorkflowRequest('files','GET',{id:state.files[0].id})).file;if(first.stage===stage)state.selected=first;}}catch(error){state.error=error.message;}finally{state.loading=false;if(document.body.dataset.activeDepartment==='requistion'&&requistionOutputStage()===stage)renderRequistion(stage==='print'?'print':'input-report');}}
function requistionOutputView(stage){const state=requistionOutputState[stage];if(!state.loaded&&!state.loading&&!state.error)setTimeout(()=>requistionLoadOutput(stage),0);return '<section class="requistion-output-files no-print"><div class="requistion-approval-file-heading"><h3>'+(stage==='print'?'Print':'Requistion List')+'</h3><button type="button" data-requistion-output-refresh="'+stage+'" '+(state.loading?'disabled':'')+'>Refresh</button></div><p role="status">'+esc(state.loading?'Loading…':state.error)+'</p><div class="table-wrap"><table><thead><tr><th>Date</th><th>Department</th><th>Requistion</th><th>Prepared by</th>'+(stage==='print'?'<th>Requistion List Date</th>':'')+'<th>Action</th></tr></thead><tbody>'+state.files.map(file=>'<tr><td>'+esc(file.date)+'</td><td>'+esc(file.requester.department)+'</td><td>'+esc(file.requester.requistion||'Requistion')+'</td><td>'+esc(file.requester.name)+'</td>'+(stage==='print'?'<td>'+esc(file.archiveOn||'')+'</td>':'')+'<td><button type="button" data-requistion-output-open="'+esc(file.id)+'" data-stage="'+stage+'">Open</button> <button type="button" data-requistion-output-print="'+esc(file.id)+'" data-stage="'+stage+'">Print</button></td></tr>').join('')+(!state.files.length?'<tr><td colspan="6">'+(state.loading?'Loading…':stage==='print'?'সম্পূর্ণ Approval করা ফাইল এখানে থাকবে।':'তিন কর্মদিবস পরে ফাইল এখানে স্থায়ীভাবে থাকবে।')+'</td></tr>':'')+'</tbody></table></div>'+(state.files.length<state.total?'<button type="button" data-requistion-output-more="'+stage+'">Load more</button>':'')+'</section>'+(state.selected?'<div class="requistion-output-actions no-print"><button type="button" data-requistion-output-print="'+esc(state.selected.id)+'" data-stage="'+stage+'">Print A4</button></div>'+requistionOutputPaper(state.selected):'');}
$('#main').addEventListener('click',async event=>{if(document.body.dataset.activeDepartment!=='requistion')return;const button=event.target.closest('button');if(!button)return;if(button.dataset.requistionOutputRefresh)return void requistionLoadOutput(button.dataset.requistionOutputRefresh);if(button.dataset.requistionOutputMore)return void requistionLoadOutput(button.dataset.requistionOutputMore,true);const id=button.dataset.requistionOutputOpen||button.dataset.requistionOutputPrint,stage=button.dataset.stage;if(!id||!requistionOutputState[stage])return;const action=button.dataset.requistionOutputPrint?'print':'view',page=stage==='print'?'requistion-print':'requistion-input-report';if(!window.FarnoorAccess.canAction(page,action)){toast('এই কাজের অনুমতি নেই।');return;}button.disabled=true;try{const file=(await requistionWorkflowRequest('files','GET',{id})).file;if(file.stage!==stage){await requistionLoadOutput(stage);toast('ফাইলটি এখন Requistion List-এ আছে।');return;}requistionOutputState[stage].selected=file;renderRequistion(stage==='print'?'print':'input-report');if(button.dataset.requistionOutputPrint){await Promise.all([...document.querySelectorAll('.requistion-new-paper img')].map(image=>image.decode?.().catch(()=>{})));await document.fonts?.ready;window.print();}}catch(error){toast(error.message);button.disabled=false;}});
window.setInterval?.(()=>{const stage=requistionOutputStage();if(document.body.dataset.activeDepartment==='requistion'&&stage&&!document.hidden)void requistionLoadOutput(stage);},60000);
document.addEventListener?.('visibilitychange',()=>{const stage=requistionOutputStage();if(!document.hidden&&document.body.dataset.activeDepartment==='requistion'&&stage)void requistionLoadOutput(stage);});

